import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { canonicalBytes, canonicalJsonV2, HASH_SCHEME_V2, sha256Hex } from "../src/integrity/index.js";

interface Vector {
  name: string;
  input: unknown;
  canonical?: string;
  canonical_utf8_hex?: string;
  sha256?: string;
  error?: string;
}

// RFC 8785 (hash scheme "jcs-1") vectors generated by
// tests/vectors/canonical_json_v2_vectors.py; Python and Rust assert the same file.
const { vectors, scheme } = JSON.parse(
  readFileSync(new URL("../../../tests/vectors/canonical_json_v2.json", import.meta.url), "utf8"),
) as { vectors: Vector[]; scheme: string };

function decode(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(decode);
  if (typeof value === "object" && value !== null) {
    const object = value as Record<string, unknown>;
    const keys = Object.keys(object);
    if (keys.length === 1 && keys[0] === "$f64") {
      const view = new DataView(new ArrayBuffer(8));
      view.setBigUint64(0, BigInt(`0x${object.$f64 as string}`));
      return view.getFloat64(0);
    }
    if (keys.length === 1 && keys[0] === "$bigint") return BigInt(object.$bigint as string);
    if (keys.length === 1 && keys[0] === "$str") return JSON.parse(`"${object.$str as string}"`);
    return Object.fromEntries(keys.map((key) => [key, decode(object[key])]));
  }
  return value;
}

describe("cross-language RFC 8785 vectors (jcs-1)", () => {
  it("covers the agreed set", () => {
    expect(scheme).toBe(HASH_SCHEME_V2);
    expect(vectors.length).toBeGreaterThanOrEqual(70);
    expect(new Set(vectors.map((vector) => vector.name)).size).toBe(vectors.length);
  });

  it.each(vectors.map((vector) => [vector.name, vector] as const))("matches Python for %s", (_name, vector) => {
    const value = decode(vector.input);
    if (vector.error) {
      expect(() => canonicalJsonV2(value)).toThrow();
      return;
    }
    const bytes = canonicalJsonV2(value);
    expect(Buffer.from(bytes).toString("utf8")).toBe(vector.canonical);
    expect(Buffer.from(bytes).toString("hex")).toBe(vector.canonical_utf8_hex);
    expect(sha256Hex(bytes)).toBe(vector.sha256);
    expect(Buffer.from(canonicalBytes(value, HASH_SCHEME_V2)).toString("hex")).toBe(vector.canonical_utf8_hex);
  });
});
